# Real-World: Safe Data Fetcher with Retry 🔄

```javascript
async function fetchWithRetry(fn, maxRetries = 3) {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      console.warn(`Attempt ${attempt} failed: ${err.message}`);
      if (attempt === maxRetries) {
        throw new Error(`Failed after ${maxRetries} attempts`, { cause: err });
      }
    }
  }
}

// Demo with simulated unreliable service
let tries = 0;
const unreliableService = () => new Promise((resolve, reject) => {
  tries++;
  tries < 3 ? reject(new Error("Network glitch")) : resolve("Connected successfully!");
});

fetchWithRetry(unreliableService).then(console.log);
```

